{"content":"// Package config builds the application configuration.
package config

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"time"
)

// Config holds application settings.
type Config struct {
	Host    string
	Port    int
	Debug   bool
	Workers int
	Timeout time.Duration
	Tags    []string
}

// Defaults returns the built-in configuration.
func Defaults() Config {
	return Config{Host: "localhost", Port: 8080, Workers: 4, Timeout: 30 * time.Second}
}

// Load starts from Defaults and applies environment overrides from getenv:
// APP_HOST, APP_PORT (1-65535), APP_DEBUG (strconv.ParseBool), APP_WORKERS (>= 1),
// APP_TIMEOUT (time.ParseDuration) and APP_TAGS (comma-separated).
// All invalid environment values are reported together in a single error;
// when any is invalid, the zero Config is returned.
func Load(getenv func(string) string) (Config, error) {
	c := Defaults()
	var errs []error
	if v := getenv("APP_HOST"); v != "" {
		c.Host = v
	}
	if v := getenv("APP_PORT"); v != "" {
		p, err := strconv.Atoi(v)
		if err != nil || p < 1 || p > 65535 {
			errs = append(errs, fmt.Errorf("APP_PORT: invalid port %q", v))
		} else {
			c.Port = p
		}
	}
	if v := getenv("APP_DEBUG"); v != "" {
		b, err := strconv.ParseBool(v)
		if err != nil {
			errs = append(errs, fmt.Errorf("APP_DEBUG: invalid bool %q", v))
		} else {
			c.Debug = b
		}
	}
	if v := getenv("APP_WORKERS"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil || n < 1 {
			errs = append(errs, fmt.Errorf("APP_WORKERS: invalid count %q", v))
		} else {
			c.Workers = n
		}
	}
	if v := getenv("APP_TIMEOUT"); v != "" {
		d, err := time.ParseDuration(v)
		if err != nil {
			errs = append(errs, fmt.Errorf("APP_TIMEOUT: invalid duration %q", v))
		} else {
			c.Timeout = d
		}
	}
	if v := getenv("APP_TAGS"); v != "" {
		c.Tags = parseTags(v)
	}
	if len(errs) > 0 {
		return Config{}, errors.Join(errs...)
	}
	return c, nil
}

// parseTags splits s on commas, trims each item and drops empty ones.
func parseTags(s string) []string {
	for _, item := range strings.Split(s, ",") {
		item = strings.TrimSpace(item)
		if item != "" {
			c.Tags = append(c.Tags, item)
		}
	}
}

// Merge returns base with every non-zero field of override replacing the
// corresponding field. For Tags, a non-nil override slice replaces base's
// even when empty. Neither argument is modified.
func Merge(base, override Config) Config {
	out := base
	out.Tags = base.Tags // keep base's slice; never write into it below
	if override.Host != "" {
		out.Host = override.Host
	}
	if override.Port != 0 {
		out.Port = override.Port
	}
	if override.Debug {
		out.Debug = override.Debug
	}
	if override.Workers != 0 {
		out.Workers = override.Workers
	}
	if override.Timeout != 0 {
		out.Timeout = override.Timeout
	}
	if override.Tags != nil {
		out.Tags = override.Tags
	}
	return out
}
